function SkillCard({ group, index }) {
  const ref = useRef(null)
  const [pos, setPos] = useState({ x: 0, y: 0 })
  const [hovering, setHovering] = useState(false)
  const { t } = useTranslation()

  const handleMove = (e) => {
    if (!ref.current) return
    const rect = ref.current.getBoundingClientRect()
    setPos({ x: e.clientX - rect.left, y: e.clientY - rect.top })
  }

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 30 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ delay: index * 0.12, duration: 0.5, ease: 'easeOut' }}
      onMouseMove={handleMove}
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
      className="relative rounded-xl border overflow-hidden p-5 md:p-6 transition-all duration-300"
      style={{
        borderColor: hovering ? 'rgba(108,99,255,0.4)' : 'rgba(42,42,85,0.5)',
        backgroundColor: hovering ? 'rgba(17,17,40,0.8)' : 'rgba(17,17,40,0.3)',
        boxShadow: hovering ? '0 0 30px rgba(108,99,255,0.08)' : 'none',
      }}
    >
      <div
        className="pointer-events-none absolute inset-0 transition-opacity duration-300"
        style={{
          opacity: hovering ? 1 : 0,
          background: `radial-gradient(400px circle at ${pos.x}px ${pos.y}px, rgba(${ACCENT_RGB}, 0.08), transparent 50%)`,
        }}
      />

      <motion.div
        className="pointer-events-none absolute -inset-x-full -inset-y-1/2 skew-x-[20deg]"
        style={{
          background: 'linear-gradient(90deg, transparent, rgba(108,99,255,0.02), transparent)',
        }}
        animate={{ x: ['100%', '-100%'] }}
        transition={{ duration: 8, repeat: Infinity, ease: 'linear', delay: index * 1.5 }}
      />

      <div
        className="absolute top-0 left-6 right-6 h-[1px] transition-all duration-300"
        style={{
          background: 'linear-gradient(90deg, transparent, rgba(108,99,255,0.4), transparent)',
          opacity: hovering ? 0.8 : 0.15,
        }}
      />

      <div className="relative z-10">
        <div className="flex items-center gap-3 mb-5">
          <motion.svg
            width="26"
            height="26"
            viewBox="-14 -14 28 28"
            className="shrink-0 text-dark-accent/50"
            animate={{ y: [0, -3, 0] }}
            transition={{ duration: 3, repeat: Infinity, ease: 'easeInOut', delay: index * 0.3 }}
          >
            {ICONS[group.key]}
          </motion.svg>
          <h3 className="font-display text-sm font-bold uppercase tracking-[0.15em] text-dark-text-secondary">
            {t(`skills.categories.${group.key}`)}
          </h3>
        </div>

        <div className="flex flex-wrap gap-2">
          {group.skills.map((skill, i) => (
            <motion.span
              key={skill}
              initial={{ opacity: 0, y: 8 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.04, duration: 0.3, ease: 'easeOut' }}
              className="font-mono text-[11px] px-3 py-1.5 rounded-full border transition-all duration-200 hover:-translate-y-0.5 cursor-default select-none text-dark-text-secondary/60 border-dark-border/50 hover:text-dark-accent hover:border-dark-accent/40"
