            >
              {t('contact.description')}
            </motion.p>

            <div className="relative rounded-2xl p-0.5" style={{ background: 'linear-gradient(135deg, rgba(0,212,255,0.2), rgba(255,107,157,0.1), rgba(0,212,255,0.2))' }}>
              <div
                className="rounded-2xl p-6 space-y-4"
                style={{
                  backgroundColor: 'rgba(17,17,40,0.8)',
                  backdropFilter: 'blur(12px)',
                  WebkitBackdropFilter: 'blur(12px)',
                }}
              >
                {socialLinks.map((link, i) => (
                  <SocialLink key={link.key} link={link} index={i} />
                ))}
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  )
}

