        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.6, duration: 0.5 }}
          className="font-mono text-xs text-dark-text-secondary/50 mb-12"
        >
          {'>'} The requested resource has been deallocated
        </motion.p>

        {/* Back button */}
