import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    port: 9089,
    host: '0.0.0.0',
  },
})

import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { AnimatePresence, motion } from 'framer-motion'
import Magnet from '../reactbits/Magnet'

const links = [
  { key: 'home', href: '#home' },
  { key: 'about', href: '#about' },
  { key: 'skills', href: '#skills' },
  { key: 'projects', href: '#projects' },
  { key: 'experience', href: '#experience' },
  { key: 'github', href: '#github' },
  { key: 'blog', href: '#blog' },
  { key: 'contact', href: '#contact' },
]

const sectionIds = links.map(l => l.href.slice(1))

export default function Navbar({ language, setLanguage }) {
  const { t, i18n } = useTranslation()
  const [mobileOpen, setMobileOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)
  const [activeId, setActiveId] = useState('home')

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20)
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setActiveId(entry.target.id)
          }
        }
      },
      { rootMargin: '-40% 0px -55% 0px' }
    )
    sectionIds.forEach((id) => {
      const el = document.getElementById(id)
      if (el) observer.observe(el)
    })
    return () => observer.disconnect()
  }, [])

  const toggleLang = useCallback(() => {
    const next = language === 'en' ? 'id' : 'en'
    setLanguage(next)
    i18n.changeLanguage(next)
  }, [language, setLanguage, i18n])

  return (
    <>
      <nav
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
          scrolled
            ? 'bg-dark-bg/80 backdrop-blur-xl border-b border-dark-border/30'
            : 'bg-transparent'
        }`}
      >
        <div className="max-w-6xl mx-auto px-6">
          <div className="flex items-center justify-between h-16 md:h-20">
            <a href="#home" className="font-display font-bold text-xl tracking-widest text-dark-accent">
              ARRAFI
            </a>

            <div className="hidden md:flex items-center gap-1">
              {links.map(({ key, href }) => (
                <a
                  key={key}
                  href={href}
                  className={`relative px-3 py-2 text-sm font-mono transition-colors duration-300 ${
                    activeId === href.slice(1)
                      ? 'text-dark-accent'
                      : 'text-dark-text-secondary hover:text-dark-text'
                  }`}
                >
                  {t(`nav.${key}`)}
                  {activeId === href.slice(1) && (
                    <motion.span
                      layoutId="nav-indicator"
                      className="absolute -bottom-0.5 left-1/2 -translate-x-1/2 w-1 h-1 rounded-full bg-dark-accent"
                      transition={{ type: 'spring', stiffness: 500, damping: 35 }}
                    />
                  )}
                </a>
              ))}
              <div className="ml-4 pl-4 border-l border-dark-border/50">
                <button
                  onClick={toggleLang}
                  className="px-3 py-1.5 text-xs font-mono border border-dark-border/50 text-dark-text-secondary hover:text-dark-accent hover:border-dark-accent/50 transition-all duration-300 rounded-full"
                >
                  {language === 'en' ? 'ID' : 'EN'}
                </button>
              </div>
            </div>

            <button
              className="md:hidden relative w-8 h-8 flex items-center justify-center text-dark-text-secondary hover:text-dark-accent transition-colors"
              onClick={() => setMobileOpen(!mobileOpen)}
              aria-label={mobileOpen ? 'Close menu' : 'Open menu'}
            >
              <span className="sr-only">Menu</span>
              <div className="w-5 h-4 relative flex flex-col justify-between">
                <span className={`block h-px w-full bg-current transition-all duration-300 ${mobileOpen ? 'rotate-45 translate-y-[7px]' : ''}`} />
                <span className={`block h-px w-full bg-current transition-all duration-300 ${mobileOpen ? 'opacity-0' : ''}`} />
                <span className={`block h-px w-full bg-current transition-all duration-300 ${mobileOpen ? '-rotate-45 -translate-y-[7px]' : ''}`} />
              </div>
            </button>
          </div>
        </div>
      </nav>

      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', stiffness: 300, damping: 30 }}
            className="fixed top-0 right-0 bottom-0 z-40 w-72 bg-dark-bg/95 backdrop-blur-2xl border-l border-dark-border/30 md:hidden"
          >
            <div className="flex flex-col justify-center h-full px-8 gap-2">
              {links.map(({ key, href }, i) => (
                <motion.a
